import React, { useState, useContext } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { OrderContext } from "./OrderContext";
import backgroundImage from "../Img/order8.jpg";

const AddOrder = () => {
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const [errors, setErrors] = useState({});
  const { setOrdersChanged } = useContext(OrderContext);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setOrderData({ ...orderData, [name]: value });
  };

  const sendData = (e) => {
    e.preventDefault();
    axios.post("http://localhost:5000/orders/", orderData)
      .then(() => {
        alert("Order Added");
        setOrderData({
          firstName: "",
          lastName: "",
          email: "",
          phoneNumber: "",
          address: "",
          city: "",
          orderId: "",
          specialInstructions: "",
          pickupTime: "",
          orderStatus: "",
        });
        setOrdersChanged((prev) => !prev);
        navigate("/all-orders");
      })
      .catch((err) => {
        alert(err);
      });
  };

  return (
    <div className="h-screen flex justify-center items-center bg-cover bg-center bg-gray-900/50" style={{ backgroundImage: `url(${backgroundImage})` }}>
      <div className="bg-white/80 p-8 rounded-lg shadow-lg max-w-lg w-full">
        <h1 className="text-2xl font-bold text-red-900 text-center mb-6">Add Order</h1>
        <form onSubmit={sendData} className="space-y-4">
          {[ 
            { name: "firstName", label: "First Name" },
            { name: "lastName", label: "Last Name" },
            { name: "email", label: "Email" },
            { name: "phoneNumber", label: "Phone Number" },
            { name: "address", label: "Address" },
            { name: "city", label: "City" },
            { name: "orderId", label: "Order ID" },
            { name: "specialInstructions", label: "Special Instructions" },
            { name: "pickupTime", label: "Pickup Time", type: "datetime-local" },
            { name: "orderStatus", label: "Order Status" },
          ].map((field) => (
            <div key={field.name}>
              <label className="block font-semibold">{field.label}</label>
              <input
                type={field.type || "text"}
                name={field.name}
                value={orderData[field.name]}
                onChange={handleChange}
                className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-red-900 focus:outline-none"
                placeholder={`Enter ${field.label}`}
              />
            </div>
          ))}
          <button type="submit" className="w-full bg-red-900 text-white py-2 rounded-md hover:bg-red-700">Submit</button>
        </form>
        <button onClick={() => navigate("/")} className="w-full mt-4 bg-gray-700 text-white py-2 rounded-md hover:bg-gray-500">Back to Home</button>
      </div>
    </div>
  );
};

export default AddOrder;
